mapper.select:
SELECT * FROM team
WHERE sports_meeting_id = #{sportsMeetingId}
ORDER BY create_time DESC

SELECT * FROM team
WHERE group_type_id = #{groupTypeId}
ORDER BY create_time DESC

mapper.update:
UPDATE team
name = #{name}, leader = #{leader}, coach = #{coach}, total_score = #{totalScore},
WHERE id = #{id}

UPDATE team t
SET t.total_score = COALESCE((
    SELECT SUM(r.points) FROM result r
    JOIN participant p ON r.participant_id = p.id
    WHERE p.team_id = t.id
), 0) + COALESCE((
    SELECT SUM(a.delta_amount) FROM team_score_adjustment a
    WHERE a.team_id = t.id
), 0)
WHERE t.sports_meeting_id = #{sportsMeetingId}
